21	/// Slices up the children into logical parts, processing styles and handling
22	/// things like tags and weak pagebreaks.
23	pub fn collect<'a>(
24	    mut children: &'a mut [Pair<'a>],
25	    locator: &mut SplitLocator<'a>,
26	    mut initial: StyleChain<'a>,
27	) -> Vec<Item<'a>> {
28	    // The collected page-level items.
29	    let mut items: Vec<Item<'a>> = vec![];
30	    // When this is true, an empty page should be added to `pages` at the end.
31	    let mut staged_empty_page = true;
32	
33	    // The `children` are a flat list of flow-level items and pagebreaks. This
34	    // loops splits it up into pagebreaks and consecutive slices of
35	    // non-pagebreaks. From these pieces, we build page items that we can then
36	    // layout in parallel.
37	    while let Some(&(elem, styles)) = children.first() {
38	        if let Some(pagebreak) = elem.to_packed::<PagebreakElem>() {
39	            // Add a blank page if we encounter a strong pagebreak and there was
40	            // a staged empty page.
41	            let strong = !pagebreak.weak.get(styles);
42	            if strong && staged_empty_page {
43	                let locator = locator.next(&elem.span());
44	                items.push(Item::Run(&[], initial, locator));
45	            }
46	
47	            // Add an instruction to adjust the page parity if requested.
48	            if let Some(parity) = pagebreak.to.get(styles) {
49	                let locator = locator.next(&elem.span());
50	                items.push(Item::Parity(parity, styles, locator));
51	            }
52	
53	            // The initial styles for the next page are ours unless this is a
54	            // "boundary" pagebreak. Such a pagebreak is generated at the end of
55	            // the scope of a page set rule to ensure a page boundary. Its
56	            // styles correspond to the styles _before_ the page set rule, so we
57	            // don't want to apply it to a potential empty page.
58	            if !pagebreak.boundary.get(styles) {
59	                initial = styles;
60	            }
61	
62	            // Stage an empty page after a strong pagebreak.
63	            staged_empty_page |= strong;
64	
65	            // Advance to the next child.
66	            children = &mut children[1..];
67	        } else {
68	            // Find the end of the consecutive non-pagebreak run.
69	            let end =
70	                children.iter().take_while(|(c, _)| !c.is::<PagebreakElem>()).count();
71	
72	            // Migrate start tags without accompanying end tags from before a
73	            // pagebreak to after it.
74	            let end = migrate_unterminated_tags(children, end);
75	            if end == 0 {
76	                continue;
77	            }
78	
79	            // Advance to the rest of the children.
80	            let (group, rest) = children.split_at_mut(end);
81	            children = rest;
82	
83	            // If all that is left now are tags, then we don't want to add a
84	            // page just for them (since no group would have been detected in a
85	            // tagless layout and tags should never affect the layout). For this
86	            // reason, we remember them in a `PageItem::Tags` and later insert
87	            // them at the _very start_ of the next page, even before the
88	            // header.
89	            //
90	            // We don't do this if all that's left is end boundary pagebreaks
91	            // and if an empty page is still staged, since then we can just
92	            // conceptually replace that final page with us.
93	            if group.iter().all(|(c, _)| c.is::<TagElem>())
94	                && !(staged_empty_page
95	                    && children.iter().all(|&(c, s)| {
96	                        c.to_packed::<PagebreakElem>().is_some_and(|c| c.boundary.get(s))
97	                    }))
98	            {
99	                items.push(Item::Tags(group));
100	                continue;
101	            }
102	
103	            // Record a page run and then disregard a staged empty page because
104	            // we have real content now.
105	            let locator = locator.next(&elem.span());
106	            items.push(Item::Run(group, initial, locator));
107	            staged_empty_page = false;
108	        }
109	    }
110	
111	    // Flush a staged empty page.
112	    if staged_empty_page {
113	        items.push(Item::Run(&[], initial, locator.next(&())));
114	    }
115	
116	    items
117	}
