119	/// Migrates trailing start tags without accompanying end tags from before
120	/// a pagebreak to after it. Returns the position right after the last
121	/// non-migrated tag.
122	///
123	/// This is important because we want the positions of introspectable elements
124	/// that technically started before a pagebreak, but have no visible content
125	/// yet, to be after the pagebreak. A typical case where this happens is `show
126	/// heading: it => pagebreak() + it`.
127	fn migrate_unterminated_tags(children: &mut [Pair], mid: usize) -> usize {
128	    // Compute the range from before the first trailing tag to after the last
129	    // following pagebreak.
130	    let (before, after) = children.split_at(mid);
131	    let start = mid - before.iter().rev().take_while(|&(c, _)| c.is::<TagElem>()).count();
132	    let end = mid + after.iter().take_while(|&(c, _)| c.is::<PagebreakElem>()).count();
